// Picks the FIRST sheet row whose Status column is empty and validates it.
// Rows the workflow has already rendered carry Status = "done".
const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
if (!rows.length) {
  throw new Error('The sheet returned no rows. Pick your spreadsheet and tab in BOTH Google Sheets nodes, and add the header row: Question, OptionA, OptionB, OptionC, CorrectLetter, FunFact, Status, VideoUrl.');
}

const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';
const next = rows.find((r) => isBlank(r.Status));
if (!next) {
  throw new Error('All ' + rows.length + ' quiz rows are used (Status is filled on every row). Add new questions, or clear a Status cell to re-run that row.');
}

const rowNumber = next.row_number;
if (!rowNumber) {
  throw new Error('The sheet rows have no row_number - keep the Google Sheets node on the standard "Get Row(s)" operation.');
}

const get = (k) => String(next[k] == null ? '' : next[k]).trim();
const question = get('Question');
const optionA = get('OptionA');
const optionB = get('OptionB');
const optionC = get('OptionC');
const correctLetter = get('CorrectLetter').toUpperCase();
const funFact = get('FunFact');

if (!question) throw new Error('Row ' + rowNumber + ': Question is empty.');
if (!optionA) throw new Error('Row ' + rowNumber + ': OptionA is empty.');
if (!optionB) throw new Error('Row ' + rowNumber + ': OptionB is empty.');
if (!optionC) throw new Error('Row ' + rowNumber + ': OptionC is empty.');
if (correctLetter !== 'A' && correctLetter !== 'B' && correctLetter !== 'C') {
  throw new Error('Row ' + rowNumber + ': CorrectLetter must be A, B or C (got "' + get('CorrectLetter') + '").');
}

return [{ json: { rowNumber, question, optionA, optionB, optionC, correctLetter, funFact } }];

function buildProject(config, data) {
  const cfg = config || {};
  const round = (n) => Math.round(n * 100) / 100;
  const esc = (s) =>
    String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  // ---- inputs -------------------------------------------------------------
  const question = String(data.question || '').trim();
  const options = [String(data.optionA || '').trim(), String(data.optionB || '').trim(), String(data.optionC || '').trim()];
  const correctLetter = String(data.correctLetter || '').trim().toUpperCase();
  // Long fun facts break the card layout; 200 chars is the verified ceiling.
  let funFact = String(data.funFact || '').trim();
  if (funFact.length > 200) funFact = funFact.slice(0, 197).replace(/\s+\S*$/, '') + '…';

  if (!question) throw new Error('The sheet row has no Question.');
  options.forEach((o, i) => {
    if (!o) throw new Error(`The sheet row is missing Option${'ABC'[i]}.`);
    if (o.length > 40) throw new Error(`Option${'ABC'[i]} is ${o.length} characters — keep options at 40 or fewer so the rows stay readable.`);
  });
  if (question.length > 130) throw new Error(`The Question is ${question.length} characters — keep it at 130 or fewer.`);
  const correctIndex = ['A', 'B', 'C'].indexOf(correctLetter);
  if (correctIndex === -1) throw new Error(`CorrectLetter must be A, B or C (got "${data.correctLetter}").`);

  // ---- brand knobs --------------------------------------------------------
  const accent = cfg.accentColor || '#7C6BFF';
  const bg = cfg.bgColor || '#151533';
  const bgDeep = cfg.bgDeepColor || '#0E0E24';
  const ink = bgDeep; // dark text used on accent-coloured surfaces
  const digitColors = Array.isArray(cfg.countdownColors) && cfg.countdownColors.length === 3
    ? cfg.countdownColors
    : [accent, '#FFB01F', '#FF5C5C'];

  const hexToRgb = (hex) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
    if (!m) return { r: 124, g: 107, b: 255 };
    const n = parseInt(m[1], 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  };
  const rgba = (hex, a) => { const { r, g, b } = hexToRgb(hex); return `rgba(${r},${g},${b},${a})`; };
  const lighten = (hex, f) => {
    const { r, g, b } = hexToRgb(hex);
    const L = (v) => Math.min(255, Math.round(v + (255 - v) * f));
    return `#${((1 << 24) + (L(r) << 16) + (L(g) << 8) + L(b)).toString(16).slice(1)}`;
  };

  // ---- adaptive type ------------------------------------------------------
  // Conservative width estimate: average glyph ≈ 0.58em for Sora 800,
  // 0.56em for Inter 600 (0.72em when the text is mostly capitals).
  const estLines = (text, fontPx, availPx, em) => {
    const caps = (text.match(/[A-Z]/g) || []).length;
    const letters = (text.match(/[A-Za-z]/g) || []).length || 1;
    const factor = caps / letters > 0.6 ? 0.72 : em;
    return Math.max(1, Math.ceil((text.length * factor * fontPx) / availPx));
  };

  const qLen = question.length;
  const qFont = qLen <= 45 ? 64 : qLen <= 85 ? 54 : 46;
  const qLines = estLines(question, qFont, 900, 0.58);
  const qHeight = Math.round(qLines * qFont * 1.18);

  const optMax = Math.max(...options.map((o) => o.length));
  const optFont = optMax <= 20 ? 40 : optMax <= 32 ? 36 : 31;
  // Row inner width: 900 − 2×34 padding − 56 chip − 22 gap − 3 border ≈ 750.
  const optRowHeights = options.map((o) => {
    const lines = estLines(o, optFont, 750, 0.56);
    return 60 + Math.max(56, Math.round(lines * optFont * 1.35));
  });
  const stackRows = (startY, gap) => {
    const ys = [];
    let y = startY;
    for (const h of optRowHeights) { ys.push(y); y += h + gap; }
    return { ys, end: y - gap };
  };

  // ---- scene timing -------------------------------------------------------
  const qSeconds = round(Number(cfg.questionSeconds || 6) + (qLen > 85 ? 1.2 : 0));
  const cSeconds = round(Number(cfg.countdownSeconds || 3.6));
  const rSeconds = round(Number(cfg.revealSeconds || 5.8));
  const slot = round(cSeconds / 3);

  // ---- shared text styles -------------------------------------------------
  const optionRow = (letter, text, state) => {
    // state: 'neutral' | 'correct' | 'dim'
    const isCorrect = state === 'correct';
    const boxBg = isCorrect ? accent : 'rgba(255,255,255,0.06)';
    const boxBorder = isCorrect ? accent : 'rgba(255,255,255,0.14)';
    const textColor = isCorrect ? ink : '#EDECFF';
    const chipBg = isCorrect ? ink : accent;
    const chipColor = isCorrect ? '#FFFFFF' : ink;
    // CSS-drawn check mark: no glyph-fallback risk on the render host.
    const check = isCorrect
      ? `<span style='display:inline-block; float:right; width:16px; height:32px; border-right:7px solid ${ink}; border-bottom:7px solid ${ink}; transform:rotate(45deg); margin-top:2px; margin-right:10px;'></span>`
      : '';
    return `<div style='background:${boxBg}; border:1.5px solid ${boxBorder}; border-radius:26px; padding:30px 34px; color:${textColor}; font-size:${optFont}px; font-weight:600;'><span style='display:inline-block; width:56px; height:56px; line-height:56px; text-align:center; background:${chipBg}; color:${chipColor}; border-radius:14px; font-weight:800; margin-right:22px;'>${letter}</span>${esc(text)}${check}</div>`;
  };

  // ---- scene 1 — question -------------------------------------------------
  const q = stackRows(Math.max(640, 320 + qHeight + 70), 36);
  const hintY = Math.min(1500, q.end + 90);

  const questionScene = {
    id: 'question',
    duration: qSeconds,
    backgroundColor: bg,
    transition: 'smoothup',
    transitionId: 'countdown',
    transitionDuration: 0.5,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: qSeconds,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='qzBg' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='${lighten(bg, 0.09)}'/><stop offset='1' stop-color='${bg}'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#qzBg)'/><circle cx='140' cy='250' r='130' fill='${rgba(accent, 0.14)}'/><circle cx='985' cy='520' r='60' fill='${rgba(accent, 0.1)}'/><circle cx='950' cy='1710' r='180' fill='${rgba(accent, 0.11)}'/><circle cx='90' cy='1500' r='10' fill='${rgba(accent, 0.35)}'/><circle cx='1000' cy='1240' r='8' fill='${rgba(accent, 0.3)}'/></svg>`,
      },
      {
        type: 'TEXT', x: 540, y: 140, anchor: 'top-center', track: 1,
        enterBegin: 0.2, enterEnd: 0.65, enterAnimation: 'fade', exitEnd: qSeconds,
        style: { fontFamily: 'Sora', color: '#FFFFFF' },
        html: `<div style='display:inline-block; background:${accent}; color:${ink}; border-radius:999px; padding:14px 40px; font-size:28px; font-weight:800; letter-spacing:6px;'>${esc(cfg.kicker || 'DAILY QUIZ')}</div>`,
      },
      {
        type: 'TEXT', x: 540, y: 320, width: 900, anchor: 'top-center', track: 2,
        enterBegin: 0.4, enterEnd: 0.9, enterAnimation: 'smoothup', exitEnd: qSeconds,
        style: { fontFamily: 'Sora', color: '#FFFFFF' },
        html: `<div style='text-align:center; color:#FFFFFF; font-size:${qFont}px; line-height:1.18; font-weight:800; letter-spacing:-1px;'>${esc(question)}</div>`,
      },
      ...options.map((opt, i) => ({
        type: 'TEXT', x: 90, y: q.ys[i], width: 900, anchor: 'top-left', track: 3 + i,
        enterBegin: round(0.7 + i * 0.15), enterEnd: round(1.1 + i * 0.15),
        enterAnimation: 'smoothleft', exitEnd: qSeconds,
        // The contrast lint reads style.color (the HTML cascade wins at paint
        // time, so these declarations never change the render).
        style: { fontFamily: 'Inter', color: '#EDECFF' },
        html: optionRow('ABC'[i], opt, 'neutral'),
      })),
      {
        type: 'TEXT', x: 540, y: hintY, anchor: 'top-center', track: 6,
        enterBegin: 1.5, enterEnd: 1.9, enterAnimation: 'fade', exitEnd: qSeconds,
        style: { fontFamily: 'Inter', color: '#9C97D6' },
        html: `<div style='color:#9C97D6; font-size:30px; font-weight:700; letter-spacing:2px;'>${esc(cfg.timerHint || 'You have 3 seconds — lock it in!')}</div>`,
      },
      {
        // Handle watermark. y=1560 keeps its bottom edge near y~1600, above the
        // Shorts caption strip (bottom ~300px); centred, so it also clears the
        // right-edge button rail. Content rows never reach past y~1352.
        type: 'TEXT', x: 540, y: 1560, anchor: 'top-center', track: 7,
        enterBegin: 0.9, enterEnd: 1.3, enterAnimation: 'fade', exitEnd: qSeconds,
        style: { fontFamily: 'Inter', color: '#9C97D6' },
        html: `<div style='color:#7E79B8; font-size:26px; font-weight:700; letter-spacing:5px;'>${esc(cfg.channelHandle || '')}</div>`,
      },
    ],
  };

  // ---- scene 2 — countdown ------------------------------------------------
  const countdownScene = {
    id: 'countdown',
    duration: cSeconds,
    backgroundColor: bgDeep,
    transition: 'circleopen',
    transitionId: 'reveal',
    transitionDuration: 0.55,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: cSeconds,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='qzCnt' cx='0.5' cy='0.42' r='0.9'><stop offset='0' stop-color='${lighten(bgDeep, 0.12)}'/><stop offset='1' stop-color='${bgDeep}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#qzCnt)'/><circle cx='540' cy='860' r='330' fill='none' stroke='${rgba(accent, 0.35)}' stroke-width='3'/><circle cx='540' cy='860' r='260' fill='none' stroke='${rgba(digitColors[1], 0.4)}' stroke-width='3'/><circle cx='540' cy='860' r='395' fill='none' stroke='${rgba(accent, 0.14)}' stroke-width='1.5'/></svg>`,
      },
      {
        type: 'TEXT', x: 540, y: 330, anchor: 'top-center', track: 1,
        enterBegin: 0, exitEnd: cSeconds,
        style: { fontFamily: 'Sora', color: digitColors[1] },
        html: `<div style='text-align:center; color:${digitColors[1]}; font-size:28px; font-weight:800; letter-spacing:6px;'>${esc(cfg.countdownLabel || "TIME'S TICKING")}</div>`,
      },
      ...[3, 2, 1].map((n, i) => {
        const isLast = i === 2;
        // Each digit starts entering while the previous one fades, so no frame
        // ever shows an empty ring between beats. The FIRST digit waits 0.2s
        // and finishes entering exactly as the 0.5s scene crossfade ends, so
        // it never double-exposes over the still-visible option rows.
        const begin = i === 0 ? 0.2 : round(i * slot - 0.15);
        return {
          type: 'TEXT', x: 540, y: 680, anchor: 'top-center', track: 2 + i,
          enterBegin: begin, enterEnd: round(begin + 0.3), enterAnimation: 'circleopen',
          ...(isLast
            ? { exitEnd: cSeconds }
            : { exitBegin: round((i + 1) * slot - 0.15), exitEnd: round((i + 1) * slot), exitAnimation: 'fade' }),
          style: { fontFamily: 'Sora', color: digitColors[i] },
          html: `<div style='text-align:center; color:${digitColors[i]}; font-size:260px; font-weight:800;'>${n}</div>`,
        };
      }),
    ],
  };

  // ---- scene 3 — reveal ---------------------------------------------------
  const r = stackRows(330, 36);
  const cardY = r.end + 80;
  const factLines = estLines(funFact, 34, 800, 0.53);
  const cardEnd = cardY + 72 + 40 + Math.round(factLines * 34 * 1.5);
  const ctaY = Math.max(1240, cardEnd + 130);
  const handleY = ctaY + 150;

  const revealScene = {
    id: 'reveal',
    duration: rSeconds,
    backgroundColor: bg,
    visuals: [
      {
        type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: rSeconds,
        svg: `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='qzRev' cx='0.5' cy='0.3' r='0.95'><stop offset='0' stop-color='${lighten(bg, 0.1)}'/><stop offset='1' stop-color='${bgDeep}'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#qzRev)'/><circle cx='120' cy='300' r='90' fill='${rgba(accent, 0.12)}'/><circle cx='980' cy='1680' r='150' fill='${rgba(accent, 0.1)}'/><circle cx='1005' cy='420' r='9' fill='${rgba(digitColors[1], 0.5)}'/><circle cx='80' cy='1350' r='8' fill='${rgba(accent, 0.4)}'/></svg>`,
      },
      {
        type: 'TEXT', x: 540, y: 210, anchor: 'top-center', track: 1,
        enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: rSeconds,
        style: { fontFamily: 'Sora', color: '#9C97D6' },
        html: `<div style='color:#9C97D6; font-size:30px; font-weight:800; letter-spacing:8px;'>CORRECT ANSWER</div>`,
      },
      ...options.map((opt, i) => {
        const isCorrect = i === correctIndex;
        return {
          type: 'TEXT', x: 90, y: r.ys[i], width: 900, anchor: 'top-left', track: 2 + i,
          ...(isCorrect
            ? { enterBegin: 0.65, enterEnd: 1.05, enterAnimation: 'circleopen' }
            : { enterBegin: round(0.25 + i * 0.12), enterEnd: round(0.5 + i * 0.12), enterAnimation: 'fade', opacity: 0.35 }),
          exitEnd: rSeconds,
          style: { fontFamily: 'Inter', color: isCorrect ? '#FFFFFF' : '#EDECFF' },
          html: optionRow('ABC'[i], opt, isCorrect ? 'correct' : 'dim'),
        };
      }),
      {
        type: 'TEXT', x: 540, y: cardY, width: 880, anchor: 'top-center', track: 5,
        enterBegin: 1.2, enterEnd: 1.65, enterAnimation: 'smoothup', exitEnd: rSeconds,
        style: { fontFamily: 'Inter', color: '#CFCCF2' },
        html: `<div style='background:rgba(255,255,255,0.06); border:1.5px solid rgba(255,255,255,0.14); border-radius:28px; padding:34px 40px; text-align:left;'><div style='color:${digitColors[1]}; font-size:26px; font-weight:800; letter-spacing:4px;'>DID YOU KNOW?</div><div style='margin-top:14px; color:#CFCCF2; font-size:34px; line-height:1.5; font-weight:500;'>${esc(funFact)}</div></div>`,
      },
      {
        type: 'TEXT', x: 540, y: ctaY, anchor: 'top-center', track: 6,
        enterBegin: 1.9, enterEnd: 2.3, enterAnimation: 'circleopen', exitEnd: rSeconds,
        style: { fontFamily: 'Sora', color: '#FFFFFF' },
        html: `<div style='display:inline-block; background:${accent}; color:${ink}; border-radius:999px; padding:24px 58px; font-size:32px; font-weight:800;'>${esc(cfg.ctaText || 'Follow for a new quiz every day')}</div>`,
      },
      {
        type: 'TEXT', x: 540, y: handleY, anchor: 'top-center', track: 7,
        enterBegin: 2.2, enterEnd: 2.6, enterAnimation: 'fade', exitEnd: rSeconds,
        style: { fontFamily: 'Inter', color: '#9C97D6' },
        html: `<div style='color:#7E79B8; font-size:26px; font-weight:700; letter-spacing:5px;'>${esc(cfg.brandName || '')} · ${esc(cfg.channelHandle || '')}</div>`,
      },
    ],
  };

  // ---- audio (best-effort music bed) --------------------------------------
  const music = data.music || {};
  const audios = [];
  if (cfg.musicUrl && music.ok !== false) {
    audios.push({ src: cfg.musicUrl, volume: Number(cfg.musicVolume ?? 0.16) });
  }

  const totalDuration = round(qSeconds + cSeconds + rSeconds - 0.5 - 0.55);

  const payload = {
    // Render names only allow letters, digits, spaces, _ and -.
    name: (`daily-quiz-${question}`).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120) || 'daily-quiz',
    resolution: cfg.resolution || 'youtube-short',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes: [questionScene, countdownScene, revealScene],
    audios,
  };

  return {
    payload,
    meta: {
      question,
      correctLetter,
      correctAnswer: options[correctIndex],
      funFact,
      questionFontPx: qFont,
      optionFontPx: optFont,
      sceneSeconds: { question: qSeconds, countdown: cSeconds, reveal: rSeconds },
      totalDuration,
      hasMusic: audios.length > 0,
    },
  };
}

// ---- n8n glue -----------------------------------------------------------
const cfg = $('Config').first().json;
const row = $('Pick next question').first().json;

// Music probe (HEAD request, best-effort). A dead or oversized track just
// means the video renders without a music bed - it can never fail the run.
let music = { ok: false };
try {
  const probe = $input.first().json;
  const status = Number(probe.statusCode);
  const headers = probe.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  const limit = Number(cfg.maxMusicBytes ?? 5242880);
  music = { ok: status === 200 && (!bytes || bytes <= limit), bytes };
} catch (e) { /* keep ok:false */ }

const { payload, meta } = buildProject(cfg, {
  question: row.question,
  optionA: row.optionA,
  optionB: row.optionB,
  optionC: row.optionC,
  correctLetter: row.correctLetter,
  funFact: row.funFact,
  music,
});

return [{ json: { payload, meta: { ...meta, rowNumber: row.rowNumber } } }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for the run.
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result && job.result.url) || null;

let sheetUpdated = false;
try {
  const u = $('Mark row done').first().json;
  sheetUpdated = Boolean(u) && !u.error;
} catch (e) { /* sheet write failed - reported below */ }

return [{
  json: {
    question: build.meta.question,
    correctAnswer: build.meta.correctLetter + '. ' + build.meta.correctAnswer,
    videoUrl: url,
    jobId: job.id,
    creditsCharged: build.creditsRequired,
    videoSeconds: build.meta.totalDuration,
    sheetRow: build.meta.rowNumber,
    sheetUpdated,
    nextStep: sheetUpdated
      ? 'Row marked done with the video URL. Post videoUrl as a Short, or add the YouTube tail from the sticky note.'
      : 'The render finished but the sheet write-back failed - copy videoUrl manually and check the Mark row done node.',
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview,
// then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    question: d.meta.question,
    correctAnswer: d.meta.correctLetter + '. ' + d.meta.correctAnswer,
    funFact: d.meta.funFact,
    sheetRow: d.meta.rowNumber,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalDuration,
    sceneSeconds: d.meta.sceneSeconds,
    hasMusic: d.meta.hasMusic,
    warnings: d.warnings,
    sheetNote: 'Dry runs never mark the row as used - the same question renders when you set dryRun to false.',
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render and write back to the sheet.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];
